import React from 'react';
import { Link } from 'react-router-dom';

function Nav() {
  return (
    <div>
      <nav id="navbar">
        <ul>
          <li><Link to="/art">works</Link></li>
          <li><Link to="/design">design</Link></li>
          <li><Link to="/opennotes">references + open notes</Link></li>
          <li><Link to="/about-me">about me</Link></li>
        </ul>
      </nav>
    </div>
  )
}

function Header() {
  return (
    <div>
      <header>
        <h1>corey de'juan sherrard jr</h1>
        <h2>artist + engineer</h2>
        <div id="update">
          <h3>**CURRENT**</h3>
          <h4>
            <b>Sanman Studios Arts Residency</b> in Houston, TX and
            <b> Wave Farm Radio Art Residency</b> in Acra, NY.<br/><br/>
            <i>In-Studio at Sanman Studios from March to late 2025</i>
          </h4>
        </div>
        <div id="performance-updates">
          <h3>**PERFORMANCES + DJING**</h3>
          <h4>
            <b>April 12:</b><br/> DJing at the Milam Street Block Party (<b>3223 Milam St.</b>) from 3 - 7 PM w/ <b>Pink Matter</b> & <b>Huey Bosco</b><br/><hr/>
            <b>April 24:</b><br/> The List (<b>201 Roberts St., Houston, TX</b>) from 7 PM - 12 AM w/ <b>JJ</b>
          </h4>
        </div>
      </header>
      <Nav/>
    </div>
  )
}

// copy the update div underneath at the bottom of the header tag above whenever
// you have something to share as far as updates

/*

*/
// <li><Link to="/design">design</Link></li>
// <li><Link to="/programming">programming</Link></li>

export default Header;
